const KEY='veyra-demo-v1';
const seed={company:{name:'Mein Unternehmen',email:'',address:'',vat:''},clients:[{id:'c1',name:'Muster GmbH',email:'kontakt@muster.example',address:'Musterstraße 1, 60311 Frankfurt'},{id:'c2',name:'Nordblick Studio',email:'hello@nordblick.example',address:'Hamburg'},{id:'c3',name:'Berg & Partner',email:'kontakt@berg.example',address:'Berlin'}],documents:[{id:'d1',type:'Rechnung',number:'RE-2026-0001',clientId:'c1',date:'2026-10-02',due:'2026-10-16',tax:19,status:'Bezahlt',note:'',lines:[{description:'Beratung und Konzeption',quantity:8,price:120}]},{id:'d2',type:'Rechnung',number:'RE-2026-0002',clientId:'c2',date:'2026-10-11',due:'2026-11-01',tax:19,status:'Offen',note:'',lines:[{description:'Designleistungen',quantity:1,price:2450}]},{id:'d3',type:'Rechnung',number:'RE-2026-0003',clientId:'c3',date:'2026-10-19',due:'2026-11-02',tax:19,status:'Entwurf',note:'',lines:[{description:'Workshop',quantity:2,price:490}]},{id:'d4',type:'Angebot',number:'AN-2026-0001',clientId:'c2',date:'2026-10-20',due:'2026-11-15',tax:19,status:'Entwurf',note:'',lines:[{description:'Markenstrategie',quantity:1,price:3200}]}]};
let db;try{db=JSON.parse(localStorage.getItem(KEY))||structuredClone(seed)}catch{db=structuredClone(seed)}let editing=null,creatingType='Rechnung';
const $=id=>document.getElementById(id), euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{localStorage.setItem(KEY,JSON.stringify(db));render()};
const sums=d=>{const net=d.lines.reduce((a,l)=>a+Number(l.quantity||0)*Number(l.price||0),0),tax=net*Number(d.tax||0)/100;return {net,tax,total:net+tax}};
const client=id=>db.clients.find(c=>c.id===id)?.name||'Unbekannt';
const invoices=()=>db.documents.filter(d=>d.type==='Rechnung'),quotes=()=>db.documents.filter(d=>d.type==='Angebot');
const totals=()=>({all:invoices().reduce((a,d)=>a+sums(d).total,0),paid:invoices().filter(d=>d.status==='Bezahlt').reduce((a,d)=>a+sums(d).total,0),open:invoices().filter(d=>d.status==='Offen'||d.status==='Überfällig').reduce((a,d)=>a+sums(d).total,0),drafts:invoices().filter(d=>d.status==='Entwurf').length});
function nav(page){document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id===page));document.querySelectorAll('.navitem').forEach(e=>e.classList.toggle('active',e.dataset.page===page));$('crumb').textContent=({overview:'Übersicht',invoices:'Rechnungen',clients:'Kunden',quotes:'Angebote',insights:'Auswertungen',assistant:'Veyra AI',settings:'Einstellungen'})[page];window.scrollTo(0,0);render()}
function stat(label,value,icon,foot){return `<div class="stat"><div class="stathead">${label}<span class="staticon">${icon}</span></div><div class="statvalue">${value}</div><div class="statfoot">${foot}</div></div>`}
function drawChart(id){const now=new Date(),months=Array.from({length:6},(_,i)=>new Date(now.getFullYear(),now.getMonth()-5+i,1));const values=months.map(m=>invoices().filter(d=>{const t=new Date(d.date);return t.getMonth()===m.getMonth()&&t.getFullYear()===m.getFullYear()}).reduce((a,d)=>a+sums(d).total,0));const max=Math.max(...values,1);$(id).innerHTML=months.map((m,i)=>`<div class="barcol" title="${euro(values[i])}"><div class="bar" style="height:${Math.max(2,values[i]/max*100)}%"></div><small>${m.toLocaleDateString('de-DE',{month:'short'})}</small></div>`).join('')}
function docTable(docs,type){if(!docs.length)return '<div class="empty">Noch keine Einträge vorhanden.</div>';return `<table class="datatable"><thead><tr><th>Nummer</th><th>Kunde</th><th>Datum</th><th>Status</th><th style="text-align:right">Betrag</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><strong>${esc(d.number)}</strong></td><td>${esc(client(d.clientId))}</td><td>${new Date(d.date+'T12:00:00').toLocaleDateString('de-DE')}</td><td><span class="tag ${esc(d.status)}">${esc(d.status)}</span></td><td class="amount">${euro(sums(d).total)}</td><td><div class="actions"><button class="mini" data-edit="${esc(d.id)}">Öffnen</button><button class="mini" data-print="${esc(d.id)}">PDF ↗</button>${d.type==='Angebot'?`<button class="mini" data-convert="${esc(d.id)}">→ Rechnung</button>`:''}${d.type==='Rechnung'&&d.status!=='Bezahlt'?`<button class="mini" data-paid="${esc(d.id)}">✓ Bezahlt</button>`:''}</div></td></tr>`).join('')}</tbody></table>`}
function render(){const t=totals();$('invoiceCount').textContent=invoices().length;const stats=stat('Gesamtes Rechnungsvolumen',euro(t.all),'€','Alle erfassten Rechnungen')+stat('Bereits bezahlt',euro(t.paid),'↗','<b>Zahlungseingang erfasst</b>')+stat('Offene Forderungen',euro(t.open),'◷','Noch nicht als bezahlt markiert')+stat('Rechnungsentwürfe',String(t.drafts).padStart(2,'0'),'▤','Warten auf Bearbeitung');$('stats').innerHTML=stats;$('insightStats').innerHTML=stats;drawChart('chart');drawChart('insightChart');$('recentTable').innerHTML=docTable(invoices().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5));const q=($('invoiceSearch')?.value||'').toLowerCase(),filter=$('invoiceFilter')?.value||'all';$('invoicesTable').innerHTML=docTable(invoices().filter(d=>(filter==='all'||d.status===filter)&&(d.number.toLowerCase().includes(q)||client(d.clientId).toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date)));$('quotesTable').innerHTML=docTable(quotes().sort((a,b)=>b.date.localeCompare(a.date)));$('clientsTable').innerHTML=`<table class="datatable"><thead><tr><th>Kunde</th><th>E-Mail</th><th>Adresse</th><th>Dokumente</th></tr></thead><tbody>${db.clients.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.email)}</td><td>${esc(c.address)}</td><td>${db.documents.filter(d=>d.clientId===c.id).length}</td></tr>`).join('')}</tbody></table>`;$('companyName').value=db.company.name||'';$('companyEmail').value=db.company.email||'';$('companyAddress').value=db.company.address||'';$('companyVat').value=db.company.vat||''}
const today=()=>new Date().toISOString().slice(0,10),plusDays=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
function addLine(l={description:'',quantity:1,price:0}){const item=document.createElement('div');item.className='line';item.innerHTML=`<label>Leistung<input class="description" placeholder="Beschreibung" required value="${esc(l.description)}"></label><label>Menge<input class="quantity" type="number" min="0.01" step="any" required value="${Number(l.quantity)}"></label><label>Einzelpreis €<input class="price" type="number" min="0" step="0.01" required value="${Number(l.price)}"></label><button type="button" class="removeLine" title="Position entfernen">×</button>`;item.querySelector('.removeLine').onclick=()=>{item.remove();calculate()};item.querySelectorAll('input').forEach(e=>e.addEventListener('input',calculate));$('lines').appendChild(item);calculate()}
function getLines(){return Array.from(document.querySelectorAll('#lines .line')).map(e=>({description:e.querySelector('.description').value.trim(),quantity:Number(e.querySelector('.quantity').value),price:Number(e.querySelector('.price').value)}))}
function calculate(){const s=sums({lines:getLines(),tax:Number($('taxRate').value)});$('subTotal').textContent=euro(s.net);$('taxTotal').textContent=euro(s.tax);$('grandTotal').textContent=euro(s.total)}
function openDocument(type='Rechnung',d=null){editing=d?.id||null;creatingType=type;$('modal').classList.add('open');$('modalTitle').textContent=d?`${type} bearbeiten`:`${type} erstellen`;$('docType').value=type;$('docClient').innerHTML=db.clients.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('docClient').value=d?.clientId||db.clients[0]?.id;$('docDate').value=d?.date||today();$('docDue').value=d?.due||plusDays(14);$('taxRate').value=String(d?.tax??19);$('docNote').value=d?.note||'';$('lines').innerHTML='';(d?.lines||[{description:'',quantity:1,price:0}]).forEach(addLine);calculate()}
function makeNumber(type){const prefix=type==='Rechnung'?'RE':'AN';const year=new Date().getFullYear();const used=db.documents.filter(d=>d.number.startsWith(`${prefix}-${year}-`)).map(d=>Number(d.number.split('-').pop())).filter(Number.isFinite);return `${prefix}-${year}-${String(Math.max(0,...used)+1).padStart(4,'0')}`}
function closeModal(){$('modal').classList.remove('open')}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400)}
function printDoc(id){const d=db.documents.find(d=>d.id===id);if(!d)return;const s=sums(d),c=db.clients.find(c=>c.id===d.clientId)||{};const w=window.open('','_blank');if(!w){toast('Popup wurde blockiert. Popups erlauben.');return}w.document.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${esc(d.number)}</title><style>body{font:14px Arial,sans-serif;color:#263344;max-width:780px;margin:55px auto;padding:20px}header{display:flex;justify-content:space-between;margin-bottom:90px}.logo{font-size:30px;font-weight:bold;color:#198b70}h1{font-size:27px}table{width:100%;border-collapse:collapse;margin-top:40px}th,td{padding:13px;border-bottom:1px solid #ddd;text-align:left}th:last-child,td:last-child{text-align:right}.sum{text-align:right;margin-top:25px;line-height:2}.muted{color:#7e8995;font-size:12px}footer{margin-top:100px;border-top:1px solid #ddd;padding-top:15px;font-size:11px}@media print{body{margin:20mm auto}}</style></head><body><header><div class="logo">✳ veyra.</div><div>${esc(db.company.name)}<br>${esc(db.company.address)}<br>${esc(db.company.email)}<br>${esc(db.company.vat)}</div></header><div class="muted">An: ${esc(c.name)} · ${esc(c.address)}</div><h1>${esc(d.type)} ${esc(d.number)}</h1><p>Ausgestellt: ${esc(d.date)} &nbsp; · &nbsp; ${d.type==='Rechnung'?'Fällig':'Gültig bis'}: ${esc(d.due)}</p><table><tr><th>Position</th><th>Menge</th><th>Einzelpreis</th><th>Gesamt</th></tr>${d.lines.map(l=>`<tr><td>${esc(l.description)}</td><td>${l.quantity}</td><td>${euro(l.price)}</td><td>${euro(l.quantity*l.price)}</td></tr>`).join('')}</table><div class="sum">Netto ${euro(s.net)}<br>USt. (${d.tax} %) ${euro(s.tax)}<br><strong>Gesamt ${euro(s.total)}</strong></div><p>${esc(d.note)}</p><footer>Veyra Demo-Dokument · Nicht auf steuerliche Vollständigkeit geprüft · Kein XRechnung/ZUGFeRD-Export.</footer><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function parseText(){const raw=$('assistantInput').value.trim();if(!raw)return toast('Bitte beschreibe die Rechnung.');const name=(raw.match(/(?:an|für)\s+([\p{L}\d& .-]+?)(?=\s+(?:über|mit|für|,|\.|\d+\s*(?:Stunden|Stück))|$)/iu)||[])[1]?.trim();const amount=(raw.match(/(\d+(?:[,.]\d+)?)\s*(?:Stunden|Std\.?|Stück|Einheiten)/i)||[])[1];const price=(raw.match(/(?:zu\s*(?:je|jeweils)?|à|je)\s*(\d+(?:[,.]\d+)?)\s*(?:€|Euro)/i)||raw.match(/(\d+(?:[,.]\d+)?)\s*(?:€|Euro)/i)||[])[1];const q=amount?Number(amount.replace(',','.')):1,p=price?Number(price.replace(',','.')):0;let id=db.clients.find(c=>c.name.toLowerCase()===name?.toLowerCase())?.id;if(name&&!id){id=crypto.randomUUID();db.clients.push({id,name,email:'',address:''});save()}openDocument('Rechnung');if(id)$('docClient').value=id;$('lines').innerHTML='';addLine({description:raw.match(/(?:über\s+\d+\s+(?:Stunden|Stück)\s+)(.*?)(?:\s+zu\s+|\s+à\s+|$)/i)?.[1]?.trim()||'Leistung gemäß Beschreibung',quantity:q,price:p});toast('Entwurf vorbereitet. Bitte alle Angaben sorgfältig prüfen.');nav('invoices')}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]')?.dataset.page;if(page){nav(page);return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='create'){openDocument();return}const id=e.target.closest('[data-edit]')?.dataset.edit;if(id){const d=db.documents.find(d=>d.id===id);openDocument(d.type,d);return}const pid=e.target.closest('[data-print]')?.dataset.print;if(pid){printDoc(pid);return}const paid=e.target.closest('[data-paid]')?.dataset.paid;if(paid){const d=db.documents.find(d=>d.id===paid);d.status='Bezahlt';save();toast('Als bezahlt markiert.');return}const convert=e.target.closest('[data-convert]')?.dataset.convert;if(convert){const d=db.documents.find(d=>d.id===convert);openDocument('Rechnung',{...d,id:null,type:'Rechnung'});return}});
$('documentForm').addEventListener('submit',e=>{e.preventDefault();const lines=getLines();if(!lines.length||lines.some(l=>!l.description||l.quantity<=0||l.price<0))return toast('Bitte Positionen prüfen.');const type=$('docType').value,d={id:editing||crypto.randomUUID(),type,number:editing?db.documents.find(x=>x.id===editing).number:makeNumber(type),clientId:$('docClient').value,date:$('docDate').value,due:$('docDue').value,tax:Number($('taxRate').value),note:$('docNote').value,lines,status:editing?db.documents.find(x=>x.id===editing).status:'Entwurf'};if(editing)db.documents=db.documents.map(x=>x.id===editing?d:x);else db.documents.unshift(d);save();closeModal();nav(type==='Rechnung'?'invoices':'quotes');toast(`${type} gespeichert.`)});
$('docType').addEventListener('change',()=>creatingType=$('docType').value);$('taxRate').addEventListener('change',calculate);$('addLine').onclick=()=>addLine();$('closeModal').onclick=closeModal;$('cancelModal').onclick=closeModal;$('helpCreate').onclick=()=>openDocument();$('addQuote').onclick=()=>openDocument('Angebot');$('addClient').onclick=()=>$('clientModal').classList.add('open');$('closeClient').onclick=$('cancelClient').onclick=()=>$('clientModal').classList.remove('open');$('clientForm').onsubmit=e=>{e.preventDefault();db.clients.push({id:crypto.randomUUID(),name:$('clientName').value,email:$('clientEmail').value,address:$('clientAddress').value});save();$('clientForm').reset();$('clientModal').classList.remove('open');toast('Kunde gespeichert.')};$('invoiceSearch').oninput=render;$('invoiceFilter').onchange=render;$('parsePrompt').onclick=parseText;
$('saveSettings').onclick=()=>{db.company={name:$('companyName').value,email:$('companyEmail').value,address:$('companyAddress').value,vat:$('companyVat').value};save();toast('Unternehmensprofil gespeichert.')};function exportJson(){download('veyra-daten.json',JSON.stringify({version:1,...db},null,2))}$('exportData').onclick=exportJson;$('exportSettings').onclick=exportJson;$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(!Array.isArray(incoming.clients)||!Array.isArray(incoming.documents)||!incoming.company)throw Error();if(!confirm('Aktuelle lokale Daten durch diese Datei ersetzen?'))return;db={company:incoming.company,clients:incoming.clients,documents:incoming.documents};save();toast('Daten importiert.')}catch{toast('Ungültige Sicherungsdatei.')}e.target.value=''};$('notification').onclick=()=>toast('Veyra ist aktuell eine lokale Demo ohne Benachrichtigungsdienst.');
render();
